## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/amlLogic.ts`

```typescript
/**
 * AML Decision Engine — Clinical Logic
 * Based on:
 * - ASH 2025 Guidelines for Treating Newly Diagnosed AML in Older Adults
 *   (Sekeres MA et al., Blood Advances 2025, PMID: 39970951)
 * - ELN 2022 Recommendations for AML (Döhner H et al., Blood 2022, PMID: 34521987)
 * - ELN 2024 Risk Stratification Update (Döhner H et al., Blood 2024, PMID: 38838239)
 * - VIALE-A Trial: Venetoclax + Azacitidine (DiNardo CD et al., NEJM 2020, PMID: 32558338)
 * - NCCN AML Guidelines v2.2025
 */

// ─── Input Types ─────────────────────────────────────────────────────────────

export type FitnessCategory = "fit" | "unfit" | "bsc_only";
export type ELNRisk = "favorable" | "intermediate" | "adverse" | "apl";
export type TherapyRecommendation =
  | "ic_7_3"
  | "ic_7_3_midostaurin"
  | "ic_7_3_ivosidenib"
  | "ic_7_3_enasidenib"
  | "atra_ato"
  | "alt_hma_ven"
  | "alt_hma_ven_flt3i"
  | "alt_hma_ven_ivosidenib"
  | "alt_hma_ven_enasidenib"
  | "alt_hma_mono"
  | "alt_ldac_ven"
  | "alt_ldac_mono"
  | "bsc";

export type TransplantRecommendation =
  | "not_recommended_cr1"
  | "consider_cr1"
  | "strongly_recommended_cr1"
  | "recommended_cr1"
  | "not_candidate"
  | "after_alt_response";

export interface AMLInput {
  // Patient demographics
  age: number;
  ecogPS: 0 | 1 | 2 | 3 | 4;

  // Fitness factors
  creatinine: "normal" | "elevated_1_5x" | "elevated_2x_plus";
  bilirubin: "normal" | "elevated_1_5x" | "elevated_2x_plus";
  ejectionFraction: "normal_45plus" | "reduced_35_44" | "severely_reduced";
  hctCI: 0 | 1 | 2 | 3 | 4; // HCT-CI score
  patientPreference: "aggressive" | "moderate" | "minimal" | "bsc";

  // AML subtype
  isAPL: boolean; // t(15;17) / PML::RARA
  isSecondaryAML: boolean; // Prior MDS, MPN, or therapy-related
  isRelapsedRefractory: boolean;

  // Cytogenetics
  karyotype:
    | "normal"
    | "favorable_t8_21"
    | "favorable_inv16"
    | "complex_3plus"
    | "monosomal"
    | "minus5_del5q"
    | "minus7"
    | "minus17_abn17p"
    | "t6_9"
    | "t9_11"
    | "kmt2a_rearranged"
    | "other_intermediate"
    | "other_adverse";

  // Molecular mutations
  npm1Mutation: boolean;
  flt3ITD: boolean;
  flt3ITDAllelicRatio: "low" | "high" | "na"; // <0.5 = low, ≥0.5 = high
  flt3TKD: boolean;
  idh1Mutation: boolean;
  idh2Mutation: boolean;
  tp53Mutation: boolean;
  runx1Mutation: boolean;
  asxl1Mutation: boolean;
  bcorMutation: boolean;
  cebpaDoubleMutation: boolean;

  // Treatment context
  hasHLAMatchedSibling: boolean;
  hasMatchedUnrelatedDonor: boolean;
  priorHCT: boolean;
}

// ─── Output Types ─────────────────────────────────────────────────────────────

export interface AMLRecommendation {
  fitnessCategory: FitnessCategory;
  elnRisk: ELNRisk;
  primaryTherapy: TherapyRecommendation;
  primaryTherapyLabel: string;
  primaryTherapyRationale: string;
  transplantRecommendation: TransplantRecommendation;
  transplantLabel: string;
  transplantRationale: string;
  targetedAdditions: string[];
  keyWarnings: string[];
  postRemissionPlan: string;
  references: { id: string; text: string }[];
  urgencyFlag: "routine" | "urgent" | "emergent";
}

// ─── Fitness Assessment ───────────────────────────────────────────────────────

export function assessFitness(input: AMLInput): FitnessCategory {
  // Best supportive care only
  if (input.ecogPS === 4) return "bsc_only";
  if (input.patientPreference === "minimal" || input.patientPreference === "bsc") return "bsc_only";

  // Unfit criteria (ASH 2025 / ELN 2022)
  const unfitFactors: string[] = [];

  if (input.age >= 75) unfitFactors.push("age_75plus");
  if (input.ecogPS >= 3) unfitFactors.push("ecog_3plus");
  if (input.hctCI >= 3) unfitFactors.push("hct_ci_3plus");
  if (input.creatinine === "elevated_2x_plus") unfitFactors.push("renal_severe");
  if (input.bilirubin === "elevated_2x_plus") unfitFactors.push("hepatic_severe");
  if (input.ejectionFraction === "severely_reduced") unfitFactors.push("ef_severe");

  // Moderate unfit factors
  const moderateUnfitFactors: string[] = [];
  if (input.age >= 65 && input.age < 75) moderateUnfitFactors.push("age_65_74");
  if (input.ecogPS === 2) moderateUnfitFactors.push("ecog_2");
  if (input.hctCI === 2) moderateUnfitFactors.push("hct_ci_2");
  if (input.creatinine === "elevated_1_5x") moderateUnfitFactors.push("renal_moderate");
  if (input.bilirubin === "elevated_1_5x") moderateUnfitFactors.push("hepatic_moderate");
  if (input.ejectionFraction === "reduced_35_44") moderateUnfitFactors.push("ef_reduced");

  if (unfitFactors.length >= 1) return "unfit";
  if (moderateUnfitFactors.length >= 2) return "unfit";
  return "fit";
}

// ─── ELN Risk Classification ──────────────────────────────────────────────────

export function classifyELNRisk(input: AMLInput): ELNRisk {
  if (input.isAPL) return "apl";

  // Adverse risk (ELN 2022)
  if (input.tp53Mutation) return "adverse";
  if (input.karyotype === "complex_3plus") return "adverse";
  if (input.karyotype === "monosomal") return "adverse";
  if (input.karyotype === "minus5_del5q") return "adverse";
  if (input.karyotype === "minus7") return "adverse";
  if (input.karyotype === "minus17_abn17p") return "adverse";
  if (input.karyotype === "t6_9") return "adverse";
  if (input.karyotype === "other_adverse") return "adverse";
  if (input.runx1Mutation && !input.npm1Mutation) return "adverse";
  if (input.asxl1Mutation && !input.npm1Mutation) return "adverse";
  if (input.bcorMutation && !input.npm1Mutation) return "adverse";

  // Favorable risk (ELN 2022)
  if (input.karyotype === "favorable_t8_21") return "favorable";
  if (input.karyotype === "favorable_inv16") return "favorable";
  if (input.cebpaDoubleMutation) return "favorable";
  if (input.npm1Mutation && !input.flt3ITD) return "favorable";

  // Intermediate risk
  return "intermediate";
}

// ─── Therapy Selection ────────────────────────────────────────────────────────

export function selectTherapy(
  fitness: FitnessCategory,
  elnRisk: ELNRisk,
  input: AMLInput
): { therapy: TherapyRecommendation; label: string; rationale: string } {
  if (fitness === "bsc_only") {
    return {
      therapy: "bsc",
      label: "Best Supportive Care",
      rationale:
        "Patient is not a candidate for active leukemia-directed therapy based on performance status or patient preference. Focus on quality of life, symptom management, and transfusion support.",
    };
  }

  // APL — special pathway
  if (elnRisk === "apl") {
    return {
      therapy: "atra_ato",
      label: "ATRA + ATO (All-trans retinoic acid + Arsenic trioxide)",
      rationale:
        "APL (t(15;17)/PML::RARA) is treated with ATRA + ATO, not standard 7+3 chemotherapy. This is a highly effective regimen with cure rates >90% for low/intermediate-risk APL.",
    };
  }

  if (fitness === "fit") {
    // Fit patients — intensive chemotherapy
    if (input.flt3ITD || input.flt3TKD) {
      return {
        therapy: "ic_7_3_midostaurin",
        label: "7+3 Induction + Midostaurin (FLT3 inhibitor)",
        rationale:
          "FLT3 mutation detected. ASH 2025 Rec 7 suggests adding an FLT3 inhibitor to induction therapy. Midostaurin (RATIFY trial) is standard with 7+3 for FLT3-mutated AML in fit patients.",
      };
    }
    if (input.idh1Mutation) {
      return {
        therapy: "ic_7_3_ivosidenib",
        label: "7+3 Induction + Ivosidenib (IDH1 inhibitor)",
        rationale:
          "IDH1 mutation detected. Ivosidenib in combination with induction chemotherapy is an option for fit patients with IDH1-mutated AML (IVY trial data).",
      };
    }
    if (input.idh2Mutation) {
      return {
        therapy: "ic_7_3_enasidenib",
        label: "7+3 Induction + Enasidenib (IDH2 inhibitor)",
        rationale:
          "IDH2 mutation detected. Enasidenib may be added to induction for IDH2-mutated AML in fit patients, though evidence is less robust than for IDH1.",
      };
    }
    return {
      therapy: "ic_7_3",
      label: "Standard 7+3 Induction Chemotherapy (Cytarabine + Anthracycline)",
      rationale:
        "Fit patient without actionable mutations. Standard 7+3 (cytarabine 100-200 mg/m²/day × 7 days + daunorubicin or idarubicin × 3 days) remains the standard induction regimen.",
    };
  }

  // Unfit patients — less-intensive therapy (ALT)
  if (input.idh1Mutation) {
    return {
      therapy: "alt_hma_ven_ivosidenib",
      label: "HMA (Azacitidine) + Venetoclax + Ivosidenib",
      rationale:
        "IDH1 mutation in unfit patient. ASH 2025 Rec 5a suggests AZA + ivosidenib > AZA alone. HMA + venetoclax + ivosidenib is an emerging option with strong rationale (Rec 5b).",
    };
  }
  if (input.idh2Mutation) {
    return {
      therapy: "alt_hma_ven_enasidenib",
      label: "HMA (Azacitidine) + Venetoclax",
      rationale:
        "IDH2 mutation in unfit patient. ASH 2025 Rec 5d suggests HMA + venetoclax > HMA + enasidenib. Standard HMA + venetoclax is preferred for IDH2-mutated unfit AML.",
    };
  }
  if (input.flt3ITD || input.flt3TKD) {
    return {
      therapy: "alt_hma_ven_flt3i",
      label: "HMA (Azacitidine) + Venetoclax ± FLT3 Inhibitor",
      rationale:
        "FLT3 mutation in unfit patient. ASH 2025 Rec 7 conditionally suggests adding an FLT3 inhibitor to ALT. HMA + venetoclax is the backbone; FLT3 inhibitor addition is conditional (low certainty evidence).",
    };
  }

  // Standard unfit: HMA + venetoclax (Rec 4c — strongest recommendation)
  return {
    therapy: "alt_hma_ven",
    label: "HMA (Azacitidine) + Venetoclax",
    rationale:
      "ASH 2025 Rec 4c (conditional recommendation, moderate certainty): HMA + venetoclax is preferred over HMA alone for unfit patients. VIALE-A trial demonstrated superior OS vs azacitidine monotherapy (14.7 vs 9.6 months median OS).",
  };
}

// ─── Transplant Recommendation ────────────────────────────────────────────────

export function recommendTransplant(
  fitness: FitnessCategory,
  elnRisk: ELNRisk,
  input: AMLInput
): { recommendation: TransplantRecommendation; label: string; rationale: string } {
  if (fitness === "bsc_only" || input.priorHCT) {
    return {
      recommendation: "not_candidate",
      label: "Not a transplant candidate",
      rationale: input.priorHCT
        ? "Prior HCT limits repeat transplant eligibility. Discuss with transplant center."
        : "Patient is not a candidate for active therapy; transplant is not appropriate.",
    };
  }

  if (elnRisk === "apl") {
    return {
      recommendation: "not_recommended_cr1",
      label: "Transplant not recommended in CR1 for APL",
      rationale:
        "APL treated with ATRA + ATO achieves >90% cure rates without transplant. Allo-HCT is reserved for relapsed/refractory APL.",
    };
  }

  if (elnRisk === "favorable" && fitness === "fit") {
    return {
      recommendation: "not_recommended_cr1",
      label: "Transplant not recommended in CR1 (Favorable Risk)",
      rationale:
        "ELN 2022: Favorable risk AML (t(8;21), inv(16), NPM1 mut without FLT3-ITD, biallelic CEBPA) does not benefit from allo-HCT in CR1. Consolidation with HiDAC is standard.",
    };
  }

  if (elnRisk === "adverse" && fitness === "fit") {
    const donorAvailable = input.hasHLAMatchedSibling || input.hasMatchedUnrelatedDonor;
    return {
      recommendation: donorAvailable ? "strongly_recommended_cr1" : "recommended_cr1",
      label: donorAvailable
        ? "Allo-HCT strongly recommended in CR1 (Adverse Risk)"
        : "Allo-HCT recommended in CR1 — Donor search urgently needed",
      rationale:
        "ELN 2022: Adverse risk AML has high relapse risk with chemotherapy alone. Allo-HCT in CR1 is strongly recommended. " +
        (donorAvailable
          ? "Donor available — proceed with transplant planning."
          : "No matched donor identified — initiate urgent unrelated donor search (NMDP/DKMS)."),
    };
  }

  if (elnRisk === "intermediate" && fitness === "fit") {
    return {
      recommendation: "consider_cr1",
      label: "Consider Allo-HCT in CR1 (Intermediate Risk)",
      rationale:
        "ELN 2022: Intermediate risk AML — transplant decision depends on MRD status after induction. MRD-positive after consolidation: transplant recommended. MRD-negative: transplant may be deferred. Discuss with transplant center.",
    };
  }

  if (fitness === "unfit") {
    return {
      recommendation: "after_alt_response",
      label: "Consider Allo-HCT after ALT response (if transplant-eligible)",
      rationale:
        "ASH 2025 Rec 8: For older adults who respond to ALT and have nonfavorable prognosis, allo-HCT is conditionally suggested over no transplant. Assess transplant eligibility after response.",
    };
  }

  return {
    recommendation: "consider_cr1",
    label: "Consider Allo-HCT based on MRD and clinical factors",
    rationale: "Transplant decision should be individualized based on MRD status, donor availability, and patient fitness.",
  };
}

// ─── Targeted Additions ───────────────────────────────────────────────────────

export function getTargetedAdditions(input: AMLInput, fitness: FitnessCategory): string[] {
  const additions: string[] = [];

  if (input.flt3ITD || input.flt3TKD) {
    if (fitness === "fit") {
      additions.push("Midostaurin 50 mg BID (days 8-21 of induction and consolidation) — RATIFY trial");
    }
    additions.push("Consider sorafenib or gilteritinib as maintenance post-transplant (FLT3+)");
  }

  if (input.idh1Mutation) {
    additions.push("Ivosidenib (IDH1 inhibitor) — add to induction (fit) or HMA backbone (unfit)");
  }

  if (input.idh2Mutation) {
    additions.push("Enasidenib (IDH2 inhibitor) — less evidence for combination; HMA+VEN preferred (ASH 2025 Rec 5d)");
  }

  if (input.tp53Mutation) {
    additions.push(
      "TP53 mutation: Consider decitabine-cedazuridine (oral decitabine) or clinical trial. Prognosis is poor with standard therapy."
    );
  }

  if (input.isSecondaryAML) {
    additions.push(
      "Secondary AML (prior MDS/MPN or therapy-related): Consider CPX-351 (liposomal daunorubicin/cytarabine) if fit — superior OS vs 7+3 in secondary AML (NEJM 2017)"
    );
  }

  return additions;
}

// ─── Warnings ─────────────────────────────────────────────────────────────────

export function getWarnings(input: AMLInput, elnRisk: ELNRisk): string[] {
  const warnings: string[] = [];

  if (input.isAPL) {
    warnings.push(
      "APL EMERGENCY: Initiate ATRA immediately upon morphologic suspicion — do not wait for molecular confirmation. Differentiation syndrome risk."
    );
  }

  if (input.tp53Mutation) {
    warnings.push(
      "TP53 mutation confers very poor prognosis. Median OS <6 months with standard therapy. Clinical trial enrollment strongly encouraged."
    );
  }

  if (input.karyotype === "monosomal" || input.karyotype === "complex_3plus") {
    warnings.push(
      "Complex/monosomal karyotype: Adverse ELN risk. Transplant in CR1 is strongly recommended if patient is eligible."
    );
  }

  if (input.isRelapsedRefractory) {
    warnings.push(
      "Relapsed/Refractory AML: Standard salvage regimens (MEC, FLAG-IDA) have limited efficacy. Clinical trial enrollment is strongly encouraged. Gilteritinib for FLT3+ R/R AML (ADMIRAL trial)."
    );
  }

  if (input.age >= 75 && input.flt3ITD) {
    warnings.push(
      "FLT3 inhibitor benefit in patients ≥75 receiving HMA+VEN is uncertain (ASH 2025 Rec 7 remark). Discuss risk/benefit carefully."
    );
  }

  if (input.priorHCT) {
    warnings.push("Prior HCT: Standard salvage options are limited. Discuss with transplant center regarding second transplant eligibility.");
  }

  return warnings;
}

// ─── Post-Remission Plan ──────────────────────────────────────────────────────

function getPostRemissionPlan(fitness: FitnessCategory, elnRisk: ELNRisk, input: AMLInput): string {
  if (fitness === "bsc_only") return "Focus on comfort measures and transfusion support per patient preference.";

  if (elnRisk === "apl") {
    return "APL: After CR with ATRA+ATO, consolidation with 2 cycles of ATO + ATRA. Maintenance: ATRA ± 6-MP/MTX × 2 years for high-risk APL. Monitor PML::RARA by PCR.";
  }

  if (fitness === "fit") {
    if (elnRisk === "favorable") {
      return "Consolidation: HiDAC (cytarabine 3 g/m² q12h, days 1/3/5) × 3-4 cycles. No transplant in CR1. Monitor MRD; transplant if MRD+ or relapse.";
    }
    if (elnRisk === "adverse") {
      return "Allo-HCT in CR1 strongly recommended. Proceed with donor search immediately. If no donor: HiDAC consolidation as bridge. Consider maintenance with targeted agents post-transplant.";
    }
    return "Intermediate risk: HiDAC consolidation × 1-2 cycles. Assess MRD after consolidation. MRD-positive → allo-HCT. MRD-negative → consider transplant vs additional consolidation based on risk factors.";
  }

  // Unfit
  return "Continue HMA + venetoclax indefinitely until progression or unacceptable toxicity (ASH 2025 Rec 6). Assess transplant eligibility if good response achieved. Monitor CBC every 2-4 weeks during induction.";
}

// ─── Main Assessment Function ─────────────────────────────────────────────────

export function assessAML(input: AMLInput): AMLRecommendation {
  const fitnessCategory = assessFitness(input);
  const elnRisk = classifyELNRisk(input);
  const { therapy, label, rationale } = selectTherapy(fitnessCategory, elnRisk, input);
  const { recommendation: transplantRec, label: transplantLabel, rationale: transplantRationale } = recommendTransplant(
    fitnessCategory,
    elnRisk,
    input
  );
  const targetedAdditions = getTargetedAdditions(input, fitnessCategory);
  const keyWarnings = getWarnings(input, elnRisk);
  const postRemissionPlan = getPostRemissionPlan(fitnessCategory, elnRisk, input);

  // Urgency
  let urgencyFlag: "routine" | "urgent" | "emergent" = "routine";
  if (input.isAPL) urgencyFlag = "emergent";
  else if (input.isRelapsedRefractory || elnRisk === "adverse") urgencyFlag = "urgent";

  const references = [
    {
      id: "ash2025",
      text: "Sekeres MA et al. ASH 2025 Guidelines for Treating Newly Diagnosed AML in Older Adults. Blood Advances. 2025. PMID: 39970951",
    },
    {
      id: "eln2022",
      text: "Döhner H et al. Diagnosis and Management of AML in Adults: 2022 ELN Recommendations. Blood. 2022;140(12):1345–1377. PMID: 34521987",
    },
    {
      id: "eln2024",
      text: "Döhner H et al. ELN 2024 Risk Stratification Update for AML. Blood. 2024. PMID: 38838239",
    },
    {
      id: "viale_a",
      text: "DiNardo CD et al. Azacitidine and Venetoclax in Previously Untreated AML (VIALE-A). NEJM. 2020;383(7):617–629. PMID: 32558338",
    },
    {
      id: "ratify",
      text: "Stone RM et al. Midostaurin plus Chemotherapy for AML with FLT3 Mutation (RATIFY). NEJM. 2017;377(5):454–464. PMID: 28644114",
    },
  ];

  return {
    fitnessCategory,
    elnRisk,
    primaryTherapy: therapy,
    primaryTherapyLabel: label,
    primaryTherapyRationale: rationale,
    transplantRecommendation: transplantRec,
    transplantLabel,
    transplantRationale,
    targetedAdditions,
    keyWarnings,
    postRemissionPlan,
    references,
    urgencyFlag,
  };
}

// ─── Label Helpers ────────────────────────────────────────────────────────────

export function getFitnessLabel(fitness: FitnessCategory): string {
  switch (fitness) {
    case "fit":
      return "Fit for Intensive Chemotherapy";
    case "unfit":
      return "Unfit for Intensive Chemotherapy (ALT Candidate)";
    case "bsc_only":
      return "Best Supportive Care Only";
  }
}

export function getELNRiskLabel(risk: ELNRisk): string {
  switch (risk) {
    case "favorable":
      return "Favorable Risk (ELN 2022)";
    case "intermediate":
      return "Intermediate Risk (ELN 2022)";
    case "adverse":
      return "Adverse Risk (ELN 2022)";
    case "apl":
      return "APL (t(15;17)/PML::RARA) — Special Pathway";
  }
}

export function getELNRiskColor(risk: ELNRisk): string {
  switch (risk) {
    case "favorable":
      return "text-green-700 bg-green-50 border-green-200";
    case "intermediate":
      return "text-yellow-700 bg-yellow-50 border-yellow-200";
    case "adverse":
      return "text-red-700 bg-red-50 border-red-200";
    case "apl":
      return "text-purple-700 bg-purple-50 border-purple-200";
  }
}

export function getFitnessColor(fitness: FitnessCategory): string {
  switch (fitness) {
    case "fit":
      return "text-blue-700 bg-blue-50 border-blue-200";
    case "unfit":
      return "text-orange-700 bg-orange-50 border-orange-200";
    case "bsc_only":
      return "text-gray-700 bg-gray-50 border-gray-200";
  }
}
